<?php
declare(strict_types=1);
require_once __DIR__ . '/accounts_common.php';
$user=qbook_require_user();qbook_require_role($user,['ADMIN']);production_require_method('POST');$input=production_input();
accounts_endpoint(function() use($user,$input): array {$id=(int)($input['expense_id']??0);$action=strtoupper(trim((string)($input['action']??'')));if($id<=0||!in_array($action,['APPROVE','CORRECTION_REQUIRED','CANCELLED_NOT_SPENT'],true))accounts_fail('INVALID_REVIEW_ACTION');$reason=production_clean_text($input['reason']??'',500,'REVIEW_REASON_REQUIRED',$action!=='APPROVE');$db=production_db();return accounts_transaction($db,function() use($db,$user,$id,$action,$reason): array {$s=$db->prepare("SELECT e.*,r.reference_no,b.ledger_account_id FROM qbook_general_expenses e LEFT JOIN qbook_general_expense_references r ON r.expense_id=e.id LEFT JOIN qbook_bank_accounts b ON b.id=e.bank_account_id WHERE e.id=? FOR UPDATE");$s->execute([$id]);$e=$s->fetch();if(!$e)accounts_fail('EXPENSE_NOT_FOUND',404);if($action==='CORRECTION_REQUIRED'){if($e['status']!=='SUBMITTED')accounts_fail('EXPENSE_NOT_REVIEWABLE',409);$db->prepare("UPDATE qbook_general_expenses SET status='CORRECTION_REQUIRED',reviewed_by=?,reviewed_at=UTC_TIMESTAMP(),review_reason=? WHERE id=?")->execute([(int)$user['id'],$reason,$id]);$status='CORRECTION_REQUIRED';}elseif($action==='CANCELLED_NOT_SPENT'){if(!in_array($e['status'],['SUBMITTED','CORRECTION_REQUIRED'],true))accounts_fail('EXPENSE_NOT_CANCELLABLE',409);$db->prepare("UPDATE qbook_general_expenses SET status='CANCELLED_NOT_SPENT',reviewed_by=?,reviewed_at=UTC_TIMESTAMP(),review_reason=? WHERE id=?")->execute([(int)$user['id'],$reason,$id]);$status='CANCELLED_NOT_SPENT';}else{if($e['status']!=='SUBMITTED'||$e['journal_id']!==null)accounts_fail('EXPENSE_NOT_REVIEWABLE',409);$header=accounts_money_minor($e['amount'],false);$lines=accounts_load_expense_lines($db,'qbook_general_expense_lines',$id,true);$journalLines=[];$sum=0;foreach($lines as $line){$minor=accounts_money_minor($line['amount'],false);$sum+=$minor;$journalLines[]=['account_id'=>(int)$line['expense_account_id'],'debit_minor'=>$minor,'credit_minor'=>0,'client_id'=>$line['client_id'],'project_id'=>$line['project_id'],'mixer_id'=>$line['mixer_id'],'description'=>$line['item_description']];}if($lines===[]||$sum!==$header)accounts_fail('EXPENSE_LINE_TOTAL_MISMATCH');$journalLines[]=['account_id'=>(int)$e['ledger_account_id'],'debit_minor'=>0,'credit_minor'=>$header,'description'=>(string)$e['description']];$journal=accounts_post_journal($db,$user,['transaction_date'=>$e['expense_date'],'description'=>'Bank-paid expense: '.$e['description'],'source_module'=>'GENERAL_EXPENSE','source_record_id'=>$id,'approved_by'=>(int)$user['id']],$journalLines);$db->prepare("UPDATE qbook_general_expenses SET status='APPROVED',journal_id=?,reviewed_by=?,reviewed_at=UTC_TIMESTAMP(),review_reason=NULL WHERE id=? AND journal_id IS NULL")->execute([$journal['id'],(int)$user['id'],$id]);$status='APPROVED';if($e['created_from_statement_row_id']!==null){$rowId=(int)$e['created_from_statement_row_id'];$db->prepare("INSERT INTO qbook_bank_matches(statement_row_id,source_type,source_record_id,matched_by) VALUES(?,'GENERAL_EXPENSE',?,?)")->execute([$rowId,$id,(int)$user['id']]);$db->prepare("UPDATE qbook_bank_statement_rows SET status='RECONCILED',potential_source_type='GENERAL_EXPENSE',potential_source_id=? WHERE id=?")->execute([$id,$rowId]);}}
$reference=accounts_general_expense_reference($e['reference_no']);accounts_audit($db,$user,'GENERAL_EXPENSE_'.$status,'GENERAL_EXPENSE',$id,['reference_no'=>$reference,'reason'=>$reason]);return ['expense'=>['id'=>$id,'reference_no'=>$reference,'status'=>$status]];});});
